 const saveCurrentProject=async(silent=false)=>{if(!projectId)return;try{const record:SavedProject={id:projectId,name:projectName.trim()||"Dự án chưa đặt tên",updatedAt:Date.now(),version:1,mode,videoFormat,clipStart,clipEnd,verticalThumbnailName,verticalThumbnailBlob:verticalThumbnailFileRef.current,verticalImageBlobs:[...verticalImageFilesRef.current],verticalMotionClipNames:[...verticalMotionClipNames],verticalMotionClipBlobs:[...verticalMotionClipFilesRef.current],audioName,audioBlob:audioFileRef.current,thumbnailName,thumbnailBlob:thumbnailFileRef.current,introDuration,imageBlobs:[...imageFilesRef.current],motionClipNames:[...motionClipNames],motionClipBlobs:[...motionClipFilesRef.current],original,literal,vietnamese,rows,textStyles,textPositions,activePreset,lyricShadow,style,story,motion,atmosphere,motionEnabled};await putMvProject(record);localStorage.setItem("pulse-mv-last-project",projectId);setProjectList(await listMvProjects());setProjectStatus(`${silent?"Đã tự lưu":"Đã lưu"} · ${new Date(record.updatedAt).toLocaleTimeString("vi-VN",{hour:"2-digit",minute:"2-digit"})}`)}catch{setProjectStatus("Không đủ bộ nhớ để lưu media. Hãy xóa dự án cũ hoặc clip không dùng.")}};
