 const removeCurrentProject=async()=>{if(!window.confirm(`Xóa dự án “${projectName}” khỏi trình duyệt này?`))return;setProjectReady(false);await deleteMvProject(projectId);const remaining=await listMvProjects();setProjectList(remaining);if(remaining[0]){const saved=await loadMvProject(remaining[0].id);if(saved)await restoreProject(saved)}else resetProjectFields(crypto.randomUUID());setProjectReady(true)};
 const distributeText=(key:"original"|"literal",value:string)=>{const normalized=cleanLyricText(value),lines=split(normalized);if(key==="original")setOriginal(normalized);else setLiteral(normalized);setRows(current=>current.map((row,index)=>({...row,[key]:lines[index]||""})))};
 const checkLocalEngine=async():Promise<EngineStatus>=>{setEngineStatus("checking");try{const response=await fetch("http://127.0.0.1:8765/health",{signal:AbortSignal.timeout(5000)});if(!response.ok)throw new Error();const health=await response.json() as {mvRender?:boolean;mvIntroSeparate?:boolean;mvExactTextSize?:boolean;mvPreviewParity?:boolean;mvVietnameseTextRepair?:boolean;mvUnifiedFont?:boolean;mvDynamicLineGap?:boolean;mvVerticalMotion?:boolean;mvVerticalLyricLayout?:boolean;mvManualLyricPositions?:boolean;mvSmartLyricWrap?:boolean;lineStartAlignment?:boolean;mvUnifiedTimeline?:boolean;mvExportLyricLead?:boolean};const status:EngineStatus=health.mvRender&&health.mvIntroSeparate&&health.mvExactTextSize&&health.mvPreviewParity&&health.mvVietnameseTextRepair&&health.mvUnifiedFont&&health.mvDynamicLineGap&&health.mvVerticalMotion&&health.mvVerticalLyricLayout&&health.mvManualLyricPositions&&health.mvSmartLyricWrap&&health.lineStartAlignment&&health.mvUnifiedTimeline&&health.mvExportLyricLead?"ready":"outdated";setEngineStatus(status);return status}catch{setEngineStatus("offline");return"offline"}};
 const startLocalEngine=async():Promise<EngineStatus>=>{setNote("Đang chuẩn bị bộ dựng video…");setShowEngineSetup(false);const launcher=document.createElement("iframe");launcher.hidden=true;launcher.src="pulsecharts-audio://start";document.body.appendChild(launcher);window.setTimeout(()=>launcher.remove(),4000);for(let attempt=0;attempt<8;attempt++){await new Promise(resolve=>window.setTimeout(resolve,1500));const status=await checkLocalEngine();if(status==="ready"){setNote("Bộ dựng đã sẵn sàng. Đang bắt đầu tạo video…");return status}if(status==="outdated"){setShowEngineSetup(true);setNote("Bộ dựng cần được cập nhật một lần.");return status}}setShowEngineSetup(true);setNote("Máy này chưa cài bộ dựng video. Hãy bấm CÀI MỘT LẦN bên dưới.");return"offline"};
 const updateVietnamese=(value:string)=>{const normalized=cleanLyricText(value),lines=split(normalized);setVietnamese(normalized);setRows(current=>{if(!current.length)return current;if(current.length!==lines.length){setAiAlignStatus("Số câu lời Việt đã thay đổi. Hãy tạo lại timeline để hệ thống nghe và căn lại.");return []}return current.map((row,index)=>({...row,vietnamese:lines[index]||""}))})};
 const generateTimeline=async()=>{
  const file=audioFileRef.current,lines=split(vietnamese),originalLines=split(original),literalLines=split(literal);
  if(!file){setAiAlignStatus("Hãy nạp bài cover trước.");return}
  if(!lines.length){setAiAlignStatus("Hãy dán lời Việt, mỗi câu một dòng.");return}
  const alignmentEngine=await checkLocalEngine();if(alignmentEngine!=="ready"){setShowEngineSetup(true);setAiAlignStatus(alignmentEngine==="outdated"?"Bộ nghe bài cần cập nhật để bắt đúng đầu từng câu. Hãy bấm CÀI MỘT LẦN rồi tạo lại timeline.":"Bộ nghe bài trên máy chưa chạy. Hãy mở Pulse Charts Audio AI rồi bấm KIỂM TRA KẾT NỐI.");return}
  setAiAligning(true);setAiAlignStatus("Đang tách giọng, nghe toàn bộ bài và đối chiếu từng câu. Lần đầu có thể mất vài phút…");
  try{
   const form=new FormData();form.append("file",file,file.name);form.append("lyrics",lines.join("\n"));
   const response=await fetch("http://127.0.0.1:8765/align-lyrics",{method:"POST",body:form,signal:AbortSignal.timeout(20*60*1000)});
   const payload=await response.json() as {times?:number[];ends?:number[];recognizedWords?:number;detail?:string};
   if(!response.ok)throw new Error(payload.detail||"Bộ nghe bài báo lỗi.");
   if(!Array.isArray(payload.times)||payload.times.length!==lines.length)throw new Error("Timeline trả về không đủ số câu.");
   const times=payload.times.map(Number);if(times.some((value,index)=>!Number.isFinite(value)||(index>0&&value<times[index-1])))throw new Error("Timeline không hợp lệ.");
   const detectedEnds=Array.isArray(payload.ends)&&payload.ends.length===lines.length?payload.ends.map(Number):[];
   setRows(lines.map((line,index)=>{const suggested=estimateLyricEnd(times[index],times[index+1],line,duration),detected=detectedEnds[index],maximumEnd=times[index+1]??(duration||detected);return{time:times[index],end:Number.isFinite(detected)&&detected>times[index]?Math.min(detected,maximumEnd):suggested,vietnamese:line,original:originalLines[index]||"",literal:literalLines[index]||""}}));
   setAiAlignStatus(`Hoàn tất ${lines.length} câu · nhận dạng ${payload.recognizedWords||0} từ. Bấm vào một dòng timeline để nghe lại đúng đoạn.`);
  }catch(error){
   const message=error instanceof Error&&error.message!=="Failed to fetch"?error.message:"Bộ nghe bài đã mất kết nối.";
   setEngineStatus("offline");setAiAlignStatus(`Chưa tạo timeline: ${message} Hãy mở lại Pulse Charts Audio AI rồi kiểm tra kết nối.`);
  }finally{setAiAligning(false)}
 };
 const playTimelineLine=(index:number)=>{const audio=audioRef.current;if(!audio)return;audio.currentTime=rows[index]?.time??0;setTime(audio.currentTime);void audio.play()};
 const applyClipRange=(start:number,end:number)=>{const maximum=duration||Math.max(end,60),safeStart=Math.max(0,Math.min(start,Math.max(0,maximum-.5))),safeEnd=Math.max(safeStart+.5,Math.min(end,maximum));setClipStart(safeStart);setClipEnd(safeEnd)};
 const updateClipBoundary=(field:"start"|"end",value:string)=>{const parsed=parseStamp(value);if(!Number.isFinite(parsed))return false;if(field==="start")applyClipRange(parsed,Math.max(parsed+.5,clipEnd));else applyClipRange(clipStart,parsed);return true};
 const useCurrentAsClipStart=()=>{const start=row?.time??time,length=Math.max(5,clipEnd-clipStart||30);applyClipRange(start,start+length)};
 const previewSelectedClip=()=>{const audio=audioRef.current;if(!audio||clipEnd<=clipStart)return;audio.pause();audio.currentTime=clipStart;setTime(clipStart);setIntroActive(false);exportEndRef.current=clipEnd;void audio.play();setNote(`Đang nghe thử đoạn ${stamp(clipStart)} — ${stamp(clipEnd)}.`)};
 const handleAudioMetadata=(audio:HTMLAudioElement)=>{const value=audio.duration;setDuration(value);setClipEnd(current=>Math.min(value,Math.max(.5,current||Math.min(60,value))));setClipStart(current=>Math.min(current,Math.max(0,value-.5)))};
 const updateTimelineTime=(index:number,field:"time"|"end",value:string)=>{const parsed=parseStamp(value);if(!Number.isFinite(parsed))return false;let accepted=true;setRows(current=>current.map((item,itemIndex)=>{if(itemIndex!==index)return item;const previousEnd=index>0?current[index-1].end:0,nextStart=current[index+1]?.time??(duration||Number.MAX_SAFE_INTEGER);if(field==="time"){const next=Math.min(item.end-.05,Math.max(previousEnd,parsed));if(next>=item.end){accepted=false;return item}return{...item,time:next}}const next=Math.min(nextStart,Math.max(item.time+.05,parsed));if(next<=item.time){accepted=false;return item}return{...item,end:next}}));return accepted};
 const downloadLrc=()=>{if(!rows.length)return;const lrcLines=rows.flatMap(row=>[`[${stamp(row.time)}.${String(Math.round(row.time%1*100)).padStart(2,"0")}]${cleanLyricText(row.vietnamese)}`,`[${stamp(row.end)}.${String(Math.round(row.end%1*100)).padStart(2,"0")}]`]),body=lrcLines.join("\n"),url=URL.createObjectURL(new Blob([body],{type:"text/plain;charset=utf-8"})),anchor=document.createElement("a");anchor.href=url;anchor.download=(audioName||"cover").replace(/\.[^.]+$/,"")+".lrc";anchor.click();window.setTimeout(()=>URL.revokeObjectURL(url),1000)};
 const updateTextStyle=(key:LineKey,patch:Partial<TextStyle>)=>{const safePatch=patch.fontFamily?{...patch,fontFamily:safeFont(patch.fontFamily)}:patch;setActivePreset("custom");setTextStyles(current=>({...current,[key]:{...current[key],...safePatch}}))};
