 const playFromThumbnail=()=>{const audio=audioRef.current;if(!audio||!activeThumbnailUrl)return;if(introTimerRef.current!==null)window.clearTimeout(introTimerRef.current);audio.pause();audio.currentTime=videoFormat==="vertical"?clipStart:0;setTime(videoFormat==="vertical"?clipStart:0);setPlaying(false);setIntroActive(true);setNote(`Đang chiếu thumbnail ${videoFormat==="vertical"?"dọc ":""}${introDuration.toFixed(1)} giây, sau đó nhạc tự phát.`);introTimerRef.current=window.setTimeout(()=>{setIntroActive(false);introTimerRef.current=null;void audio.play()},Math.max(.5,introDuration)*1000)};
 const handleAudioEnded=()=>{stopSync();setIntroActive(Boolean(activeThumbnailUrl))};
 const makeArt=()=>window.open("https://chatgpt.com/","_blank","noopener,noreferrer");
 const renderMp4=async()=>{const isVertical=videoFormat==="vertical",outputImages=isVertical?verticalImages:images,outputFiles=isVertical?verticalImageFilesRef.current:imageFilesRef.current,outputThumbnail=isVertical?verticalThumbnailFileRef.current:thumbnailFileRef.current,audioFile=audioFileRef.current;if(!outputThumbnail||!audioFile||!outputImages.length||!outputFiles.length||!rows.length){setNote(`Cần thumbnail ${isVertical?"dọc":"ngang"}, âm thanh, tranh minh họa và timeline trước.`);return}if(isVertical&&clipEnd<=clipStart){setNote("Mốc kết thúc phải nằm sau mốc bắt đầu.");return}let rendererStatus=await checkLocalEngine();if(rendererStatus==="offline")rendererStatus=await startLocalEngine();if(rendererStatus!=="ready"){setShowEngineSetup(true);return}setShowEngineSetup(false);
  const controller=new AbortController();renderAbortRef.current=controller;setRecording(true);setNote("Hệ thống đang dựng trực tiếp ảnh + lyric + audio thành MP4. Không cần phát bài hát hoặc chia sẻ màn hình…");if(audioRef.current)audioRef.current.pause();
  try{const renderStart=isVertical?clipStart:0,renderEnd=isVertical?clipEnd:duration,renderIntro=outputThumbnail?introDuration:0,renderTimeline=toMvTimeline(rows,renderStart,renderEnd,renderIntro);const form=new FormData();form.append("audio",audioFile,audioFile.name||"audio.wav");outputFiles.forEach((file,index)=>form.append("images",file,`art-${index+1}${file.type.includes("png")?".png":".jpg"}`));const outputMotionFiles=isVertical?verticalMotionClipFilesRef.current:motionClipFilesRef.current;if(motionEnabled&&outputMotionFiles.length===outputFiles.length)outputMotionFiles.forEach((file,index)=>form.append("motion_clips",file,`motion-${index+1}.webm`));if(outputThumbnail)form.append("thumbnail",outputThumbnail,"thumbnail.jpg");form.append("rows_json",JSON.stringify(renderTimeline));form.append("timeline_space","output");form.append("styles_json",JSON.stringify(textStyles));form.append("positions_json",JSON.stringify(textPositions[videoFormat]));form.append("mode",mode);form.append("video_format",videoFormat);form.append("clip_start",String(renderStart));form.append("clip_end",String(renderEnd));form.append("intro_duration",String(renderIntro));const response=await fetch("http://127.0.0.1:8765/render-mv",{method:"POST",body:form,signal:controller.signal});if(!response.ok){let detail="";try{detail=((await response.json()) as {detail?:string}).detail||""}catch{}if(response.status===404){setEngineStatus("outdated");setShowEngineSetup(true);throw new Error("Bộ dựng cần được cập nhật một lần.")}throw new Error(detail||`Bộ dựng báo lỗi ${response.status}`)}const blob=await response.blob();if(blob.size<1024)throw new Error("File video trả về không hợp lệ.");const u=URL.createObjectURL(blob),base=(audioName||"pulse-mv").replace(/\.[^.]+$/,""),name=base+(isVertical?"-vertical":"")+".mp4";setRenderedVideoUrl(current=>{if(current)URL.revokeObjectURL(current);return u});setRenderedVideoName(name);const anchor=document.createElement("a");anchor.href=u;anchor.download=name;document.body.appendChild(anchor);anchor.click();anchor.remove();setNote(`Đã tạo xong và tải ${name} về máy.`)}catch(error){if(error instanceof DOMException&&error.name==="AbortError")setNote("Đã hủy dựng video.");else setNote(`Chưa dựng được MV: ${error instanceof Error?error.message:"lỗi không xác định"}`)}finally{renderAbortRef.current=null;setRecording(false)}
 };
