function folderDb(){return new Promise<IDBDatabase>((resolve,reject)=>{const request=indexedDB.open("pulse-mv-folders",1);request.onupgradeneeded=()=>request.result.createObjectStore("handles");request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})}
async function saveFolder(handle:CoverDirectoryHandle,key:string){const db=await folderDb();await new Promise<void>((resolve,reject)=>{const transaction=db.transaction("handles","readwrite");transaction.objectStore("handles").put(handle,key);transaction.oncomplete=()=>resolve();transaction.onerror=()=>reject(transaction.error)});db.close()}
async function loadFolder(key:string){const db=await folderDb();const handle=await new Promise<CoverDirectoryHandle|null>((resolve,reject)=>{const request=db.transaction("handles").objectStore("handles").get(key);request.onsuccess=()=>resolve((request.result as CoverDirectoryHandle|undefined)??null);request.onerror=()=>reject(request.error)});db.close();return handle}

function projectDb(){return new Promise<IDBDatabase>((resolve,reject)=>{const request=indexedDB.open("pulse-mv-projects",1);request.onupgradeneeded=()=>{const store=request.result.createObjectStore("projects",{keyPath:"id"});store.createIndex("updatedAt","updatedAt")};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})}
async function putMvProject(project:SavedProject){const db=await projectDb();await new Promise<void>((resolve,reject)=>{const transaction=db.transaction("projects","readwrite");transaction.objectStore("projects").put(project);transaction.oncomplete=()=>resolve();transaction.onerror=()=>reject(transaction.error)});db.close()}
async function loadMvProject(id:string){const db=await projectDb();const project=await new Promise<SavedProject|null>((resolve,reject)=>{const request=db.transaction("projects").objectStore("projects").get(id);request.onsuccess=()=>resolve((request.result as SavedProject|undefined)??null);request.onerror=()=>reject(request.error)});db.close();return project}
async function listMvProjects(){const db=await projectDb();const projects=await new Promise<SavedProject[]>((resolve,reject)=>{const request=db.transaction("projects").objectStore("projects").getAll();request.onsuccess=()=>resolve(request.result as SavedProject[]);request.onerror=()=>reject(request.error)});db.close();return projects.sort((a,b)=>b.updatedAt-a.updatedAt).map(({id,name,updatedAt})=>({id,name,updatedAt}))}
async function deleteMvProject(id:string){const db=await projectDb();await new Promise<void>((resolve,reject)=>{const transaction=db.transaction("projects","readwrite");transaction.objectStore("projects").delete(id);transaction.oncomplete=()=>resolve();transaction.onerror=()=>reject(transaction.error)});db.close()}

