function normalizeWords(value:string){return value.normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/đ/g,"d").replace(/[^a-z0-9\s]/g," ").split(/\s+/).filter(Boolean)}
